    invoices: $('invoiceList'), invoiceEmpty: $('invoiceEmpty'), invoiceMetrics: $('invoiceMetrics'), reports: $('reportGrid'), reportEmpty: $('reportEmpty'), reportDeliverySummary: $('reportDeliverySummary'), billingProperty: $('billingProperty'), billingDateFrom: $('billingDateFrom'), billingDateTo: $('billingDateTo'), reportProperty: $('reportProperty'), reportDateFrom: $('reportDateFrom'), reportDateTo: $('reportDateTo'), activityProperty: $('activityProperty'), activityType: $('activityType'), documentProperty: $('documentProperty'), documentSource: $('documentSource'), warrantyStatus: $('warrantyStatus'), notificationFilter: $('notificationFilter'), users: $('userList'), userEmpty: $('userEmpty'),
